## 脚本加载策略

`<script>` 标签的不同属性组合决定了脚本的加载和执行行为：

```mermaid
flowchart TD
    subgraph Normal["普通 script"]
        N1["HTML 解析"] --> N2["暂停"]
        N2 --> N3["下载脚本"]
        N3 --> N4["执行脚本"]
        N4 --> N5["继续解析"]
    end
    subgraph Async["async script"]
        A1["HTML 解析继续"]
        A2["并行下载脚本"]
        A1 --> A3["解析中..."]
        A2 --> A4["下载完成 → 暂停解析"]
        A4 --> A5["执行脚本"]
        A5 --> A6["继续解析"]
    end
    subgraph Defer["defer script"]
        D1["HTML 解析继续"]
        D2["并行下载脚本"]
        D1 --> D3["解析完成"]
        D3 --> D4["按顺序执行 defer 脚本"]
    end
```

```typescript
type ScriptStrategy = 'blocking' | 'async' | 'defer' | 'module' | 'dynamic';

function loadScript(src: string, strategy: ScriptStrategy): Promise<void> {
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = src;

    switch (strategy) {
      case 'async':
        script.async = true;
        break;
      case 'defer':
        script.defer = true;
        break;
      case 'module':
        script.type = 'module';
        break;
      case 'dynamic':
        script.async = false;
        break;
    }

    script.onload = () => resolve();
    script.onerror = () => reject(new Error(`Failed to load: ${src}`));
    document.head.appendChild(script);
  });
}

async function loadScriptsInOrder(urls: string[]): Promise<void> {
  for (const url of urls) {
    await loadScript(url, 'dynamic');
  }
}
```

> **提示：** 动态创建的 `<script>` 默认是 `async` 的。如果需要按顺序执行，需要显式设置 `script.async = false`。

